function valid(t,a){if(!a||typeof a!=='object')return false;if(t.kind!=='choice'&&(!Array.isArray(a.values)||a.values.length!==2||!a.values.every(n=>typeof n==='number'&&Number.isFinite(n))))return false;if(t.options&&(!Number.isInteger(a.choice)||a.choice<0||a.choice>=t.options.length))return false;return true;}
